import math

def is_power_of_3(n):
    if n <= 0:
        return False
    return math.log(n, 3) == int(math.log(n, 3))

def solve_system(a_prime, b_prime, p=3):
    # System:
    # 3 * (a')^2 + b' = 3^(k-1)
    # 3 * (b')^2 + a' = 3^(m-1)

    # Check Equation A: 3 * (a')^2 + b' must be a power of 3
    lhs_A = p**(p-2) * (a_prime)**(p-1) + b_prime
    if not is_power_of_3(lhs_A):
        return None

    # Check Equation B: 3 * (b')^2 + a' must be a power of 3
    lhs_B = p**(p-2) * (b_prime)**(p-1) + a_prime
    if not is_power_of_3(lhs_B):
        return None

    # If both are powers of 3, the solution (a', b') is valid for p=3
    return (a_prime, b_prime)

# Search for solutions up to a prime-safe bound (e.g., 15)
limit = 15
solutions = []

# We rely on the constraint a' != b'
for ap in range(1, limit + 1):
    for bp in range(1, limit + 1):
        if ap == bp:
            continue

        solution = solve_system(ap, bp)
        if solution:
            # Since the problem implies a <= b for the original variables,
            # we should respect the constraint a' <= b' if we assume that 
            # the solution naturally preserves the relative order, though it's not strictly required here.
            # We include both (ap, bp) and (bp, ap) results as they represent distinct ordered triples (a', b').
            solutions.append(solution)

